dsl:
BoundedContext HotelManagement {
  Aggregate Reservation {
    AggregateRoot ReservationRoot {
      Identity reservationId
      field guestName: String
      field roomType: String
      field checkInDate: Date
      field checkOutDate: Date
    }
    Entity Guest {
      field name: String
      field email: String
    }
    DomainEvent ReservationCreated {
      field reservationId: UUID
      field guestName: String
    }
  }
  Service ReservationService {
    Command CreateReservation
    Command CancelReservation
  }
}
